def validate_gdpr_consent(record):
    errors = {}

    if not record or 'consented' not in record or not isinstance(record['consented'], bool) or not record['consented']:
        errors['consented'] = "Consented must be a boolean and set to True."

    if not record['purpose'] or len(record['purpose']) == 0:
        errors['purpose'] = "Purpose must be a non-empty string."

    try:
        import datetime
        datetime.datetime.strptime(record['timestamp'], "%Y-%m-%dT%H:%M:%SZ")
    except ValueError:
        errors['timestamp'] = "Timestamp must be a UTC ISO-8601 formatted string."

    if not record['withdrawal_url'] or len(record['withdrawal_url']) == 0:
        errors['withdrawal_url'] = "Withdrawal_url must be a non-empty string."

    return errors
